#include "kernel_operator.h"
constexpr int32_t BUFFER_NUM = 1;

class KernelHuberLoss {
public:
    __aicore__ inline KernelHuberLoss() {}
    __aicore__ inline void Init(GM_ADDR predict, GM_ADDR label, GM_ADDR y, 
                                uint32_t totalLength, uint32_t blockLength,
                                uint32_t tileNum, uint32_t tileLength,
                                uint32_t lasttileLength) {
        ASSERT(AscendC::GetBlockNum() != 0 && "block dim can not be zero!");

        this->totalLength = static_cast<int32_t>(totalLength);
        this->totalLength_f32 = static_cast<float>(this->totalLength);

        this->blockLength = blockLength;
        this->tileNum = tileNum;
        this->tileLength = tileLength / BUFFER_NUM;
        this->lasttileLength = lasttileLength;

        xGm.SetGlobalBuffer((__gm__ float*)predict + this->blockLength * AscendC::GetBlockIdx(),
                            this->blockLength);
        yGm.SetGlobalBuffer((__gm__ float*)label + this->blockLength * AscendC::GetBlockIdx(),
                            this->blockLength);
        outGm.SetGlobalBuffer(
            (__gm__ float*)y + this->blockLength * AscendC::GetBlockIdx(), 32);

        this->reduce_num = this->tileNum * BUFFER_NUM;
        uint32_t reduce_align = (this->reduce_num + 31) / 32 * 32;

        pipe.InitBuffer(inQueueIN, BUFFER_NUM, this->tileLength * 2 * sizeof(float));
        pipe.InitBuffer(tempBuf, reduce_align * sizeof(float));
        pipe.InitBuffer(tmpVec, this->tileLength * sizeof(float));
    }

    __aicore__ inline void Process() {
        int32_t loopCount = this->tileNum * BUFFER_NUM;
        for (int32_t i = 0; i < loopCount; i++) {
            CopyIn(i);
            Compute(i);
        }
        AscendC::LocalTensor<float> temp1 = tempBuf.Get<float>();
        AscendC::LocalTensor<float> work = inQueueIN.AllocTensor<float>();
        AscendC::Duplicate(work, (float)0, this->tileLength);
        AscendC::ReduceSum<float>(temp1, temp1, work, this->reduce_num);

        float len = static_cast<float>(this->totalLength_f32);
        work.SetValue(0, len);
        AscendC::Div(temp1, temp1, work, 1);

        outGm.SetValue(0, temp1.GetValue(0));
        inQueueIN.FreeTensor(work);
    }

private:
    __aicore__ inline void CopyIn(int32_t progress) {
        AscendC::LocalTensor<float> inLocal = inQueueIN.AllocTensor<float>();

        if (progress == this->tileNum - 1) {
            if (progress == 0) {
                AscendC::DataCopy(inLocal[0], xGm[0], this->tileLength);
                AscendC::DataCopy(inLocal[this->tileLength], yGm[0], this->tileLength);
            } else {
                AscendC::DataCopy(
                    inLocal[0],
                    xGm[(progress - 1) * this->tileLength + this->lasttileLength],
                    this->tileLength);
                AscendC::DataCopy(
                    inLocal[this->tileLength],
                    yGm[(progress - 1) * this->tileLength + this->lasttileLength],
                    this->tileLength);
            }
        } else {
            AscendC::DataCopy(inLocal[0], xGm[progress * this->tileLength],
                    this->tileLength);
            AscendC::DataCopy(inLocal[this->tileLength], yGm[progress * this->tileLength],
                    this->tileLength);
        }
        inQueueIN.EnQue(inLocal);
    }

    __aicore__ inline void Compute(int32_t progress) {
        AscendC::LocalTensor<float> inLocal = inQueueIN.DeQue<float>();
        AscendC::LocalTensor<float> predLocal = inLocal;
        AscendC::LocalTensor<float> labelLocal = inLocal[this->tileLength];
        AscendC::LocalTensor<float> tLocal = tmpVec.Get<float>(); // scratch buffer

        // diff = predict - label -> store to tLocal
        AscendC::Sub(tLocal, predLocal, labelLocal, this->tileLength);
        // a = |diff|
        AscendC::Abs(tLocal, tLocal, this->tileLength);
        // yLocal := ones
        AscendC::Duplicate(labelLocal, (float)1.0f, this->tileLength);
        // t = a - 1 -> store to labelLocal
        AscendC::Sub(labelLocal, tLocal, labelLocal, this->tileLength);
        // |t| -> store to predLocal
        AscendC::Abs(predLocal, labelLocal, this->tileLength);
        // t + |t| -> predLocal
        AscendC::Add(predLocal, predLocal, labelLocal, this->tileLength);
        // tplus = (t + |t|) * 0.5 -> predLocal
        AscendC::Duplicate(tLocal, (float)0.5f, this->tileLength);
        AscendC::Mul(predLocal, predLocal, tLocal, this->tileLength);

        // a = t + 1 -> store to labelLocal
        AscendC::Duplicate(tLocal, (float)1.0f, this->tileLength);
        AscendC::Add(labelLocal, labelLocal, tLocal, this->tileLength);
        // a^2 -> store to labelLocal
        AscendC::Mul(labelLocal, labelLocal, labelLocal, this->tileLength);
        // (tplus)^2 -> store to predLocal
        AscendC::Mul(predLocal, predLocal, predLocal, this->tileLength);
        // 0.5 * a^2
        AscendC::Duplicate(tLocal, (float)0.5f, this->tileLength);
        AscendC::Mul(labelLocal, labelLocal, tLocal, this->tileLength);
        // 0.5 * (tplus)^2
        AscendC::Mul(predLocal, predLocal, tLocal, this->tileLength);
        // loss_vec = 0.5*a^2 - 0.5*(tplus)^2 -> store to labelLocal
        AscendC::Sub(labelLocal, labelLocal, predLocal, this->tileLength);

        // reduce sum current tile
        AscendC::ReduceSum<float>(labelLocal, labelLocal, tLocal, this->tileLength);

        // write tile sum into temp buffer
        AscendC::LocalTensor<float> temp1 = tempBuf.Get<float>();
        temp1.SetValue(progress, labelLocal.GetValue(0));

        inQueueIN.FreeTensor(inLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueueIN;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueueOUT;
    AscendC::TBuf<> tempBuf;
    AscendC::TBuf<> tmpVec;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::GlobalTensor<float> outGm;
    float totalLength_f32;
    int32_t totalLength;
    uint32_t reduce_num;
    uint32_t blockLength;
    uint32_t tileNum;
    uint32_t tileLength;
    uint32_t lasttileLength;
};

extern "C" __global__ __aicore__ void huber_loss_custom(GM_ADDR predict, GM_ADDR label, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling) {
    GET_TILING_DATA(tiling_data, tiling);
    KernelHuberLoss op;

    op.Init(predict, label, y, tiling_data.totalLength, tiling_data.blockLength,
            tiling_data.tileNum, tiling_data.tileLength, tiling_data.lasttileLength);
    op.Process();
}

